// The entry of the background page (MV3 `background.scripts`, MV2 `background.html`).
//
// It wires three modules and puts nothing on `globalThis`: the core host (the
// only holder of the WASM client, and so of any key), the lock and the router.
// Every listener is registered while the module loads, so the event that woke
// the page reaches it.
//
// The background page starts locked. If it dies, the next start is locked too:
// the keys lived in the page and went with it.

import { createCoreHost, defaultCreateClient } from "./coreHost.mjs";
// @ts-ignore -- generated by the build from handlers/*.handler.mjs
import { HANDLERS } from "./handlers.gen.mjs";
import { createLock } from "./lock.mjs";
import { createRouter } from "./router.mjs";
// @ts-ignore -- generated by the build: what differs between the variants
import { variantHooks } from "./variant.gen.mjs";

const runtime = browser.runtime;
const now = () => Date.now();

const coreHost = createCoreHost({
  createClient: defaultCreateClient,
  now,
  timers: {
    setTimeout: (fn, ms) => setTimeout(fn, ms),
    clearTimeout: (id) => clearTimeout(/** @type {any} */ (id)),
  },
});

const lock = createLock({
  alarms: browser.alarms,
  idle: browser.idle,
  storageSession: browser.storage.session,
  now,
  coreHost,
});

const router = createRouter({
  runtime,
  lock,
  coreHost,
  handlers: /** @type {readonly import("./router.mjs").Handler[]} */ (HANDLERS),
});

runtime.onConnect.addListener(router.onConnect);
runtime.onMessage.addListener(router.onMessage);

// Only the test build has hooks, and they are set up here, in the first turn of the
// page, so a port or an alarm that woke the page reaches them. `variantHooks` is null
// in a release, so a release has no test code to run.
/** @type {any} */
const hooks = variantHooks;
if (hooks) hooks.install({ browser, runtime, coreHost, now });

// A new page has no vault, whatever an earlier page left in `storage.session`.
coreHost.lock("restart").catch(() => {});
